RoostContracts={}
local function eq(a,b,s)assert(a==b,(s or "value")..": expected "..tostring(b)..", got "..tostring(a))end
local function own(p,keys)p.moves,p.pp={},{};for _,k in ipairs(keys)do p.moves[#p.moves+1]=k;p.pp[k]=moveData[k].pp end end
local function settle(b)local n,t=0,{};while b:phase()=="script" and not b.pendingLearning do n=n+1;assert(n<300,"stuck: "..tostring(b.message));t[#t+1]=b.message;b.machine:get("script"):advance()end;return table.concat(t,"|")end
local function fresh(p,e)local b=Battle(p or Pokemon("pidgey",42),e or Pokemon("diglett",1));settle(b);own(b.player,{"roost"});own(b.enemy,{"harden"});return b end
local function roost(b,who)b:runScript(function()b:setDirection(who or "player");return RoostEffect():apply(b)end);settle(b)end
local function same(before)local n=RulesRNG.snapshot();eq(n.state,before.state);eq(n.rolls,before.rolls)end
local function types(b,p,a,c)local first,second=b:effectiveTypes(p);eq(first,a);eq(second,c)end
local function act(b,i)assert(b:selectMove(i or 1));return settle(b)end
local function eventFor(b,p)for _,e in ipairs(b.conditions:events())do if e.kind=="roostEnd" and e.pokemon==p then return e end end end
function RoostContracts.run()
 local report={ok=true,passed=0,failed=0,tests={}};local saved=RulesRNG.snapshot()
 local function test(name,fn)local ok,why=pcall(fn);Autopilot.resetControls();report.tests[#report.tests+1]={name=name,ok=ok,error=not ok and tostring(why)or nil};if ok then report.passed=report.passed+1 else report.failed=report.failed+1;report.ok=false end end
 test("One exact natural Roost producer retains GenVPP10 self target7 priority0",function()
  local m=moveData.roost;eq(m.pp,10);eq(m.power,0);eq(m.accuracy,0);eq(m.targetId,7);eq(m.priority,0);eq(m.type,"flying");eq(m.category,"status");eq(m.protectable,false);eq(#m.effects,1);assert(m.effects[1]:is("RoostEffect"))
  for _,v in ipairs({{"pidgey",37},{"pidgeotto",42},{"pidgeot",44},{"spearow",33},{"fearow",41}})do assert(Pokemon(v[1],v[2]):hasMove("roost"),v[1])end
 end)
 test("Odd85HP actual Roost heals43 and installs transient before narration yield",function()
  local b=fresh();b.player.hp=1;RulesRNG.seed(2);b:runScript(function()b:setDirection("player");RoostEffect():apply(b)end)
  eq(b.message,"PIDGEY regained health!");eq(b.player.hp,44);types(b,b.player,"normal",nil);eq(b.player.type,"normal");eq(b.player.type2,"flying");eq(b:getConditionsSnapshot().player.roost,true);eq(RulesRNG.snapshot().rolls,0);settle(b)
 end)
 test("FullHP actual attempt fails spendsPP and remains Flying with Ground immunity",function()
  local b=fresh();own(b.enemy,{"earthquake"});RulesRNG.seed(23);local text=act(b)
  eq(b.player.hp,85);eq(b.player.pp.roost,9);eq(b.enemy.pp.earthquake,9);assert(text:find("But it failed!",1,true));assert(text:find("doesn't affect",1,true));eq(b:getConditionsSnapshot().player.roost,false);types(b,b.player,"normal","flying");eq(RulesRNG.snapshot().rolls,1)
 end)
 test("Successful real fasterRoost exposes grounded user to actual Earthquake3",function()
  local b=fresh();own(b.enemy,{"earthquake"});b.player.hp=1;RulesRNG.seed(23);local text=act(b)
  assert(text:find("PIDGEY used ROOST!",1,true)<text:find("DIGLETT used EARTHQUAKE!",1,true));eq(b.player.hp,41);eq(b.player.pp.roost,9);eq(b.enemy.pp.earthquake,9);eq(RulesRNG.snapshot().rolls,4);eq(RulesRNG.snapshot().state,1178867664);types(b,b.player,"normal","flying");eq(b:getConditionsSnapshot().player.roost,false)
 end)
 test("OneHP actual capped heal still removesFlying before same incoming Ground hit",function()
  local b=fresh();own(b.enemy,{"earthquake"});b.player.hp=84;RulesRNG.seed(23);act(b);eq(b.player.hp,82);eq(RulesRNG.snapshot().rolls,4);types(b,b.player,"normal","flying")
 end)
 test("Slower actual Roost keeps Flying for earlier Ground action then heals",function()
  local b=fresh(nil,Pokemon("diglett",50));own(b.enemy,{"earthquake"});b.player.hp=1;RulesRNG.seed(23);local text=act(b)
  assert(text:find("DIGLETT used EARTHQUAKE!",1,true)<text:find("PIDGEY used ROOST!",1,true));eq(b.player.hp,44);eq(RulesRNG.snapshot().rolls,1);eq(b.player.pp.roost,9)
 end)
 test("Current effective type projection handles first second pure and nonFlying identities",function()
  for _,v in ipairs({{"flying","normal","normal"},{"normal","flying","normal"},{"flying",false,"normal"},{"flying","flying","normal"},{"water",false,"water"},{"fire","flying","fire"}})do
   local b=fresh();local p=b.player;p.type,p.type2=v[1],v[2]or nil;p.hp=1;roost(b);types(b,p,v[3],nil);eq(p.type,v[1]);eq(p.type2,v[2]or nil);eq(b.effects:grounded(p),true)
  end
 end)
 test("Pure effective type matchup STAB and queries allocate no state or consume RNG",function()
  local b=fresh();local foreign=Pokemon("pidgey",42);local before=RulesRNG.snapshot();for _=1,30 do types(b,foreign,"normal","flying");eq(b:typeMatchup("ground",foreign),0);eq(b:hasType(foreign,"flying"),true)end;eq(b.conditions.members[foreign],nil);same(before)
  b.player.hp=1;roost(b);before=RulesRNG.snapshot();for _=1,30 do types(b,b.player,"normal",nil);eq(b:typeMatchup("ground",b.player),1);eq(b:hasType(b.player,"flying"),false);eq(b.effects:grounded(b.player),true)end;same(before)
 end)
 test("Actual damage path removes FlyingSTAB148to99 while raw compatibility remains148",function()
  local b=fresh();RulesRNG.seed(15);local before=calcDamage(b.player,b.enemy,moveData.gust,40,b.effects);eq(before.damage,148);eq(before.isSTAB,true)
  b.player.hp=1;roost(b);RulesRNG.seed(15);local current=calcDamage(b.player,b.enemy,moveData.gust,40,b.effects);eq(current.damage,99);eq(current.isSTAB,false);eq(RulesRNG.snapshot().rolls,2)
  RulesRNG.seed(15);eq(calcDamage(b.player,b.enemy,moveData.gust,40).damage,148)
 end)
 test("For carries actual Battle typing while direct HasType compatibility stays intrinsic",function()
  local b=fresh();local pred=For(ATTACKER,HasType("flying"));b:setDirection("player");eq(pred:check(b),true);b.player.hp=1;roost(b);eq(pred:check(b),false);eq(HasType("flying"):check(b.player),true);eq(For(ATTACKER,HasType("normal")):check(b),true)
 end)
 test("Fixed ghost damage respects pureFlyingtoNormal Roost immunity before HP or RNG",function()
  local b=fresh();b.player.type,b.player.type2="flying",nil;b.player.hp=1;roost(b);local hp=b.player.hp;local before=RulesRNG.snapshot()
  b:runScript(function()b:setDirection("enemy");b.currentMove=moveData.nightShade;DirectDamage(DEFENDER,20):apply(b)end);settle(b);eq(b.player.hp,hp);same(before)
 end)
 test("OHKO and trapping grounding share actual effective type seam",function()
  local b=fresh(nil,Pokemon("diglett",100,{natureId=0,abilitySlot="second",heldItem="none"}));local before=RulesRNG.snapshot();eq(b.effects:ohko(b.enemy,b.player,moveData.fissure),false);same(before);eq(b.effects:withdrawBlocked(b.player),false)
  b.player.hp=1;roost(b);eq(b.effects:withdrawBlocked(b.player),true);RulesRNG.seed(2);eq(b.effects:ohko(b.enemy,b.player,moveData.fissure),true);eq(RulesRNG.snapshot().rolls,1)
 end)
 test("Roost record expires at member25 before actual side26 and cannot tick replacement record",function()
  local b=fresh();b.player.hp=1;roost(b);b:runScript(function()b:setDirection("player");SideConditionEffect("lightScreen"):apply(b)end);settle(b)
  local e=assert(eventFor(b,b.player));eq(e.order,25);local old=e.record;b.player.hp=1;roost(b);assert(b.conditions.members[b.player].roost~=old);b.conditions:residual(e);eq(b:getConditionsSnapshot().player.roost,true)
  local seen;local residual=b.conditions.residual;b.conditions.residual=function(owner,event)if event.kind=="roostEnd"then seen=owner.sides.player.lightScreen.turns end;return residual(owner,event)end
  b:runScript(function()return b:finishRound()end);settle(b);eq(seen,5);eq(b.conditions.sides.player.lightScreen.turns,4);eq(b:getConditionsSnapshot().player.roost,false);types(b,b.player,"normal","flying")
 end)
 test("Native-style shared residual member tie covers poison9 and Roost25 with one draw",function()
  local b=fresh(Pokemon("pidgey",42),Pokemon("pidgey",42));for _,side in ipairs({"player","enemy"})do b[side].hp=1;roost(b,side);b[side].status="poison" end
  local trace={};local residual=b.conditions.residual;b.conditions.residual=function(owner,event)if event.pokemon then trace[#trace+1]=event.kind..":"..event.side end;return residual(owner,event)end
  RulesRNG.seed(2);b:runScript(function()return b:finishRound()end);settle(b);eq(RulesRNG.snapshot().rolls,1);eq(table.concat(trace,"|"),"status:enemy|status:player|roostEnd:enemy|roostEnd:player");eq(b.player.hp,34);eq(b.enemy.hp,34)
 end)
 test("Unequal member speeds require no residual tie or new Roost duration RNG",function()
  local b=fresh();for _,side in ipairs({"player","enemy"})do b[side].hp=1;roost(b,side)end;RulesRNG.seed(2);b:runScript(function()return b:finishRound()end);settle(b);eq(RulesRNG.snapshot().rolls,0);eq(b:getConditionsSnapshot().player.roost,false);eq(b:getConditionsSnapshot().enemy.roost,false)
 end)
 test("Invalid inactive and fainted Roost producers reject unchanged",function()
  local b=fresh();b.attacker,b.attackerSide=nil,nil;local before=RulesRNG.snapshot();eq(b.conditions:roost(),false);eq(b.conditions.members[b.player],nil);b:setDirection("player");b.player.hp=0;eq(b.conditions:roost(),false);eq(b.player.hp,0);eq(b.conditions.members[b.player],nil);same(before)
 end)
 test("Rejected publicPP and phase commands cannot heal or allocate a Roost record",function()
  local b=fresh();b.player.hp=1;b.player.pp.roost=0;local before=RulesRNG.snapshot();eq(b:selectMove(1),false);eq(b.player.hp,1);eq(b.conditions.members[b.player],nil);same(before)
  b.player.pp.roost=10;assert(b:selectMove(1));local hp=b.player.hp;eq(b:selectMove(1),false);eq(b.player.hp,hp);settle(b)
 end)
 test("Actual blocked sleep attempt spends no Roost PP installs no record and cannot heal",function()
  local b=fresh();b.player.hp=1;b.player.status="sleep";b.player.statusTurns,b.player.sleepDuration=1,1;RulesRNG.seed(2);act(b);eq(b.player.hp,1);eq(b.player.pp.roost,10);eq(b:getConditionsSnapshot().player.roost,false);types(b,b.player,"normal","flying");eq(RulesRNG.snapshot().rolls,1)
 end)
 test("Actual withdrawal clears old typing and hazard reentry restores intrinsic Flying",function()
  local p,q=Pokemon("pidgey",42),Pokemon("squirtle",100);local party=Party();assert(party:add(p));assert(party:add(q));local e=Pokemon("snorlax",100);own(e,{"harden"});local b=Battle(p,e,nil,{party=party});settle(b);p.hp=1;roost(b);assert(b:chooseParty(2));settle(b);eq(b.conditions.members[p],nil);types(b,p,"normal","flying")
  b:runScript(function()b:setDirection("enemy");b.conditions:hazard("spikes")end);settle(b);local hp=p.hp;assert(b:chooseParty(1));settle(b);eq(p.hp,hp);eq(b:getConditionsSnapshot().player.roost,false)
 end)
 test("Actual faint and forced replacement remove Roost and never pass type state",function()
  local p,q=Pokemon("pidgey",42),Pokemon("pidgey",42);local party=Party();assert(party:add(p));assert(party:add(q));local e=Pokemon("snorlax",100);own(e,{"harden"});local b=Battle(p,e,nil,{party=party});settle(b);p.hp=1;roost(b);p.hp=0
  b:runScript(function()b:setDirection("enemy");eq(b:handleFaint("player"),"replacement");return b:finishRound()end);settle(b);eq(b:phase(),"forcedSwitch");assert(b:chooseParty(2));settle(b);eq(b.player,q);types(b,q,"normal","flying");eq(b:getConditionsSnapshot().player.roost,false);eq(p.hp,0)
 end)
 test("Stale Roost expiry after clearAll cannot resurrect any member table or alter RNG",function()
  local b=fresh();b.player.hp=1;roost(b);local e=assert(eventFor(b,b.player));b:clearVolatiles();local before=RulesRNG.snapshot();b.conditions:residual(e);eq(next(b.conditions.members),nil);types(b,b.player,"normal","flying");same(before)
 end)
 test("Codec and repeated native scene draws preserve intrinsic types and trait ownership",function()
  local b=fresh();local p=b.player;p.hp=1;roost(b);local scene=BattleScene(b);scene:enter();local before=RulesRNG.snapshot();local attrs=p:attributes();for _=1,30 do scene:draw();types(b,p,"normal",nil)end;same(before)
  local data=assert(PokemonCodec.encode(p));eq(data.roost,nil);local decoded=assert(PokemonCodec.decode(data));eq(decoded.type,"normal");eq(decoded.type2,"flying");eq(decoded.hp,p.hp);eq(decoded.natureId,attrs.natureId);eq(decoded.abilitySlot,attrs.abilitySlot);eq(decoded.heldItem,attrs.heldItem);eq(p.type2,"flying");scene:exit()
 end)
 test("Actual learning suspension preserves Roost until resumed coroutine residual boundary",function()
  local b=fresh();own(b.player,{"roost"});b.player.hp=1;b:runScript(function()b:setDirection("player");RoostEffect():apply(b);b.player:gainXP(b.player:xpForLevel(45)-b.player.xp);coroutine.yield("learning",b.player);return b:finishRound()end);settle(b);assert(b.pendingLearning);local receipt,p=b:takeLearningRequest();eq(p,b.player)
  local owner={machine=StateMachine()};owner.machine:register("battle",State("battle"));local learning=LearningState(owner);owner.machine:register("learning",learning);owner.machine:change("battle");assert(LearningState.open(owner,p,function()assert(b:resumeLearning(receipt))end))
  local before=RulesRNG.snapshot();for _=1,10 do b:update();owner.machine:update();owner.machine:draw();types(b,p,"normal",nil)end;same(before);eq(p:hasMove("mirrorMove"),true)
  eq(learning.phase,"message");learning:handleInput();assert(learning.dialog.onComplete)();learning:handleInput();settle(b);eq(owner.machine:getCurrent(),"battle");eq(b:getConditionsSnapshot().player.roost,false);types(b,p,"normal","flying");eq(b:resumeLearning(receipt),false)
 end)
 test("Actual move-menu effectiveness uses battle typing without consuming RNG",function()
  local b=fresh(Pokemon("sandshrew",100),Pokemon("pidgey",42));own(b.player,{"earthquake"});local scene=BattleScene(b);scene:enter();scene.mainMenu.onSelect(1);assert(scene.moveMenu.options[1]:find(" X",1,true))
  b.enemy.hp=1;roost(b,"enemy");local before=RulesRNG.snapshot();scene:enter();scene.mainMenu.onSelect(1);assert(not scene.moveMenu.options[1]:find(" X",1,true));same(before);scene:exit()
 end)
 test("Existing type-status immunity and Worry ability override are preserved",function()
  local b=fresh(Pokemon("charizard",100));b.player.hp=1;roost(b);b:runScript(function()b:setDirection("enemy");ApplyStatus(DEFENDER,"burn"):apply(b)end);settle(b);eq(b.player.status,nil);types(b,b.player,"fire",nil)
  b:runScript(function()b:setDirection("enemy");assert(b.effects:worrySeed(b.attacker,b.defender))end);settle(b);eq(b.effects:effectiveAbility(b.player),15)
  local before=RulesRNG.snapshot();b:runScript(function()b:setDirection("enemy");ApplyStatus(DEFENDER,"sleep"):apply(b)end);settle(b);eq(b.player.status,nil);same(before)
 end)
 RulesRNG.restore(saved);return report
end
